import java.io.*;
import java.util.Arrays;

public class CF939F {
    public static final int INF = (int) 1e8;
    public static BlockReader input;
    public static PrintStream output;

    public static void main(String[] args) throws FileNotFoundException {
        if (System.getProperty("ONLINE_JUDGE") == null) {
            input = new BlockReader(new FileInputStream("D:\\DataBase\\TESTCASE\\codeforces\\CF939F.in"));
            output = System.out;
        } else {
            input = new BlockReader(System.in);
            output = new PrintStream(new BufferedOutputStream(System.out), false);
        }

        solve();

        output.flush();
    }

    public static void solve() {
        int n = input.nextInteger();
        int k = input.nextInteger();

        int[][] intervals = new int[k + 2][2];
        for (int i = 1; i <= k; i++) {
            intervals[i][0] = input.nextInteger();
            intervals[i][1] = input.nextInteger();
        }
        intervals[k + 1][0] = 2 * n;
        intervals[k + 1][1] = 2 * n;

        k++;

        // Iterative segment tree using arrays
        int size = 1;
        while (size < n + 1) size <<= 1;
        int[] tree = new int[2 * size];
        int[] lazy = new int[2 * size];
        boolean[] hasLazy = new boolean[2 * size];
        Arrays.fill(tree, INF);
        Arrays.fill(lazy, INF);
        // Initialize leaves
        for (int i = 0; i <= n; i++) {
            tree[size + i] = INF;
        }
        for (int i = size - 1; i > 0; i--) {
            tree[i] = Math.min(tree[i << 1], tree[(i << 1) | 1]);
        }

        // We'll use two trees: one for current, one for last
        int[] tree0 = tree.clone();
        int[] tree1 = tree.clone();
        boolean[] hasLazy0 = new boolean[2 * size];
        boolean[] hasLazy1 = new boolean[2 * size];
        int[] lazy0 = new int[2 * size];
        int[] lazy1 = new int[2 * size];
        // Initialize tree0 with dp[0]=0
        tree0[size] = 0;
        for (int i = size - 1; i > 0; i--) {
            tree0[i] = Math.min(tree0[i << 1], tree0[(i << 1) | 1]);
        }

        int[] data = new int[n + 1];

        for (int i = 1; i <= k; i++) {
            int[] interval = intervals[i];
            int intervalLength = interval[1] - interval[0];
            int middleLength = interval[0] - intervals[i - 1][1];

            // toArray from tree0
            for (int j = 0; j <= n; j++) {
                data[j] = query(tree0, size, j, j);
            }
            System.arraycopy(data, 0, data, Math.min(data.length, intervalLength + middleLength), Math.max(0, n + 1 - (intervalLength + middleLength)));
            Arrays.fill(data, 0, Math.min(data.length, intervalLength + middleLength), INF);

            int minX = interval[1] - middleLength - intervalLength;
            int maxX = interval[1] - middleLength;
            for (int j = 0; j <= n; j++) {
                int minNeedTime = query(tree0, size, minX - j, maxX - j);
                data[j] = Math.min(data[j], minNeedTime + 1);
            }

            for (int j = 0; j <= n; j++) {
                int minNeedTime = query(tree0, size, j - middleLength - intervalLength, j - middleLength);
                data[j] = Math.min(data[j], minNeedTime + 2);
            }

            // fromArray to tree1
            for (int j = 0; j <= n; j++) {
                update(tree1, size, j, data[j]);
            }

            // Swap trees
            int[] tempTree = tree0;
            tree0 = tree1;
            tree1 = tempTree;
            boolean[] tempLazy = hasLazy0;
            hasLazy0 = hasLazy1;
            hasLazy1 = tempLazy;
            int[] tempLazyVal = lazy0;
            lazy0 = lazy1;
            lazy1 = tempLazyVal;
        }

        int minFlipTime = query(tree0, size, n, n);

        if (minFlipTime < INF) {
            output.println("Full");
            output.println(minFlipTime);
        } else {
            output.println("Hungry");
        }
    }

    // Iterative segment tree query (range min)
    public static int query(int[] tree, int size, int l, int r) {
        if (l > r) return INF;
        l += size;
        r += size;
        int res = INF;
        while (l <= r) {
            if ((l & 1) == 1) {
                res = Math.min(res, tree[l]);
                l++;
            }
            if ((r & 1) == 0) {
                res = Math.min(res, tree[r]);
                r--;
            }
            l >>= 1;
            r >>= 1;
        }
        return res;
    }

    // Iterative segment tree point update (set value)
    public static void update(int[] tree, int size, int pos, int val) {
        pos += size;
        tree[pos] = val;
        pos >>= 1;
        while (pos > 0) {
            tree[pos] = Math.min(tree[pos << 1], tree[(pos << 1) | 1]);
            pos >>= 1;
        }
    }

    public static class BlockReader {
        static final int EOF = -1;
        InputStream is;
        byte[] dBuf;
        int dPos, dSize, next;
        StringBuilder builder = new StringBuilder();

        public BlockReader(InputStream is) {
            this(is, 4096);
        }

        public BlockReader(InputStream is, int bufSize) {
            this.is = is;
            dBuf = new byte[bufSize];
            next = nextByte();
        }

        public int nextByte() {
            while (dPos >= dSize) {
                if (dSize == -1) {
                    return EOF;
                }
                dPos = 0;
                try {
                    dSize = is.read(dBuf);
                } catch (Exception e) {
                }
            }
            return dBuf[dPos++];
        }

        public String nextBlock() {
            builder.setLength(0);
            skipBlank();
            while (next != EOF && !Character.isWhitespace(next)) {
                builder.append((char) next);
                next = nextByte();
            }
            return builder.toString();
        }

        public void skipBlank() {
            while (Character.isWhitespace(next)) {
                next = nextByte();
            }
        }

        public int nextInteger() {
            skipBlank();
            int ret = 0;
            boolean rev = false;
            if (next == '+' || next == '-') {
                rev = next == '-';
                next = nextByte();
            }
            while (next >= '0' && next <= '9') {
                ret = (ret << 3) + (ret << 1) + next - '0';
                next = nextByte();
            }
            return rev ? -ret : ret;
        }

        public int nextBlock(char[] data, int offset) {
            skipBlank();
            int index = offset;
            int bound = data.length;
            while (next != EOF && index < bound && !Character.isWhitespace(next)) {
                data[index++] = (char) next;
                next = nextByte();
            }
            return index - offset;
        }

        public boolean hasMore() {
            skipBlank();
            return next != EOF;
        }
    }
}
